files.plugin.js:
// Above the message box: the last turn's cost, time and cache share, and the conversation's cost so far.
export default function (ctx) {
  const { h } = ctx;
  function Bar() {
    const d = ctx.useData();
    if (!d || !d.session || !d.turns || !d.turns.length) return null;
    const t = d.turns[d.turns.length - 1];
    const parts = [`last turn $${t.cost.toFixed(4)}`, `${Math.round(t.secs)} s`, t.cached == null ? null : `${Math.round(100 * t.cached)}% cached`,
      `conversation $${d.session.cost.toFixed(3)}`].filter(Boolean);
    return h("div", { style: { font: "11.5px var(--font-mono)", color: "var(--muted)", padding: "2px 4px" } }, parts.join(" · "));
  }
  ctx.slots.register("composer.dock", { id: "last-turn-bar", order: 10, render: () => h(Bar) });
}
